REGION = [  # (test, note) for names with no translation: keep the proper name, add where/what
  (lambda x,y: 110<x<156 and -45<y<-9, "Avstraliya aborigenlari qabilasi"),
  (lambda x,y: x<-30 and y>10, "Shimoliy Amerika tub xalqi"),
  (lambda x,y: x<-30 and y<=10, "Janubiy Amerika tub xalqi"),
  (lambda x,y: -20<x<55 and y<15, "Afrika xalqi yoki davlati"),
]

def rule(n):
    if n in D: return D[n]
    m = re.match(r"^(.*) \((UK|GB|France|FR|Spain|Portugal|Netherlands|Dutch|Italy|IT|Belgium|USA|Soviet|USSR|RU|Danemark|Egypt)\)$", n)
    if m: return f"{rule(m.group(1)) or m.group(1)} ({OWN[m.group(2)]})"
    for pre, suf in [("Kingdom of ","qirolligi"),("Principality of ","knyazligi"),("Grand Duchy of ","buyuk gersogligi"),("Duchy of ","gersogligi"),("Sultanate of ","sultonligi"),("Emirate of ","amirligi"),("Republic of ","respublikasi"),("Viceroyalty of ","vitse-qirolligi"),("Beylik of ","bekligi")]:
        if n.startswith(pre): return f"{n[len(pre):]} {suf}"
    for en, uz in UNITS:
        if n.endswith(" "+en): return f"{n[:-len(en)-1]} {uz}"
    s = n
    for en, uz in WORDS: s = s.replace(en, uz)
    if s != n: return s[0].upper()+s[1:]
    return None

def centre(g):
    xs=[];ys=[]
    def w(c):
        if isinstance(c[0],(int,float)): xs.append(c[0]); ys.append(c[1])
        else:
            for x in c: w(x)
    w(g["coordinates"]); return (min(xs)+max(xs))/2, (min(ys)+max(ys))/2

known = {}
for line in open("../xarita-davlatlar.js", encoding="utf-8"):
    for k in re.findall(r'"([^"]+)":"', line): known[k]=1
dav_en = set(re.findall(r'en:\[([^\]]*)\]', open("../xarita-davlatlar.js", encoding="utf-8").read()))
dav_names = set(x for grp in dav_en for x in re.findall(r'"([^"]+)"', grp))
out, note, left = {}, {}, set()
for f in glob.glob("*.json"):
    if not f[:-5].lstrip("-").isdigit(): continue
    for x in json.load(open(f))["features"]:
        n = x["properties"]["NAME"]
        if n in known or n in dav_names or n in out or n in note: continue
        if not n.strip(): out[n] = "Noma'lum"; continue
        r = rule(n)
        if r: out[n] = r; continue
        if x["geometry"]:
            cx, cy = centre(x["geometry"])
            for t, lab in REGION:
                if t(cx, cy): note[n] = lab; break
        if n not in note: left.add(n)
for n in left: out[n] = n
js = "// Uzbek names for the border files, made by chegara/nomlar.py. CHEGARA_IZOH: proper names kept as is, with what they are.\n"
js += "Object.assign(window.CHEGARA_UZ, " + json.dumps(out, ensure_ascii=False, separators=(",",":")) + ");\n"
js += "window.CHEGARA_IZOH = " + json.dumps(note, ensure_ascii=False, separators=(",",":")) + ";\n"
open("nomlar.js","w",encoding="utf-8").write(js)
print("translated", len(out)-len(left), "noted", len(note), "kept", len(left))
print(" | ".join(sorted(left)))
